 String name(String id){if(Arrays.asList(SmartLists.IDS).contains(id))return Loc.t(SmartLists.name(id));if(names.containsKey(id))return names.get(id);String value;switch(id){case "continue":value="Continue watching";break;case "list":value="My List";break;case "top10":value="Top 10 this week";break;case "because":value="Because you watched…";break;case "genres":value="Genres";break;case "collections":value="Collections";break;case "recently-added":value="Recently added";break;case "services":value="Your services";break;case "recently-watched":value="Recently watched";break;case "shows":value="Your shows";break;case "movies":value="Your movies";break;case "queue":value="Your play queue";break;default:value="Coming up";}return Loc.t(value);}
