 static List<Object> jsonValues(JSONArray a){List<Object> values=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++)values.add(a.opt(i));return values;}
 static Set<String> genre(JSONObject i){Set<String> values=new LinkedHashSet<>();Object raw=i.opt("genres");if(raw instanceof JSONArray)for(Object value:jsonValues((JSONArray)raw))values.add(String.valueOf(value));else if(raw!=null)for(String value:String.valueOf(raw).split("[·,]"))if(!value.trim().isEmpty())values.add(value.trim());return values;}
