 void edit(){List<Row> rows=resolve(a.data.prefs().optJSONArray("homeLayout"),builders.keySet());LinearLayout content=a.column();content.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(10));TextView note=a.text("Continue watching stays first. Pin genres and collections below.",13,MainActivity.MUTED);content.addView(note);String[] sizes={"Small","Medium","Large"};int[] size={Arrays.asList(sizes).indexOf(cardSize())};TextView sizeLabel=a.text("Tile size",13,0xffc7c2bc);sizeLabel.setTypeface(null,android.graphics.Typeface.BOLD);sizeLabel.setPadding(0,a.dp(12),0,a.dp(2));content.addView(sizeLabel);LinearLayout sizeRow=DownloadHubActivity.pills(a,sizes,size,"home-size:",null);sizeRow.setPadding(0,0,0,a.dp(8));content.addView(sizeRow);LinearLayout list=a.column();content.addView(list);Runnable[] draw=new Runnable[1];draw[0]=()->{list.removeAllViews();for(Row row:rows){boolean locked=row.id.equals("continue"),extra=row.id.contains(":");LinearLayout line=new LinearLayout(a);line.setGravity(Gravity.CENTER_VERTICAL);Switch eye=new Switch(a);eye.setText((locked?"🔒 ":extra?"☆ ":"")+name(row.id));eye.setTextColor(MainActivity.WHITE);eye.setTextSize(14);eye.setChecked(row.visible);eye.setEnabled(!locked);eye.setContentDescription(Loc.t(extra?"Pin row":"Show row")+" "+name(row.id));eye.setOnCheckedChangeListener((b,on)->{row.visible=on;row.pinned=extra&&on;});line.addView(eye,new LinearLayout.LayoutParams(0,a.dp(56),1));for(int delta:new int[]{-1,1}){int d=delta;TextView move=a.ui.small(d<0?"▲":"▼",()->{int at=rows.indexOf(row),target=at+d;if(target<1||target>=rows.size())return;rows.remove(at);rows.add(target,row);draw[0].run();},false);move.setContentDescription(Loc.t(d<0?"Move earlier":"Move later")+" "+name(row.id));boolean enabled=!locked&&(d<0?rows.indexOf(row)>1:rows.indexOf(row)<rows.size()-1);move.setEnabled(enabled);move.setAlpha(enabled?1:.25f);line.addView(move);}list.addView(line);}};draw[0].run();ScrollView scroll=new ScrollView(a);scroll.addView(content);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(Loc.t("Make Home yours")).setView(scroll).setNegativeButton(Loc.t("Cancel"),null).setPositiveButton(Loc.t("Save Home"),(d,w)->{a.data.pref("homeCardSize",sizes[size[0]]);a.data.pref("homeLayout",encode(rows));a.render();}).create();dialog.show();}
 // Home tile size: one choice for every rail on Home (U152), saved with Edit Home.
