 // Keep ready on Home: artwork cards with the state on each one, like Continue watching (U150). It was a row of text buttons.
 void readyRail(){DataStore data=a.data;PhoneReady p=PhoneReadyJob.policy(data);List<JSONObject> rows=new ArrayList<>();Set<String> ids=new HashSet<>();
  for(JSONObject j:DataStore.objects(NoirApp.downloads.jobs()))if(j.optBoolean("readyManaged")&&ids.add(j.optString("id")))rows.add(j);
  if(p.enabled())for(JSONObject q:DataStore.objects(p.snapshot().optJSONArray("queue")))if(ids.add(q.optString("id")))rows.add(q);
  if(p.pickupEnabled())for(JSONObject q:DataStore.objects(p.snapshot().optJSONArray("pickupQueue")))if(ids.add(q.optString("id")))rows.add(q);
  if(rows.isEmpty())return;List<View> cards=new ArrayList<>();Runnable hub=()->a.startActivity(new android.content.Intent(a,DownloadHubActivity.class).putExtra("tab","ready"));
  for(JSONObject j:rows.subList(0,Math.min(20,rows.size()))){String id=j.optString("id"),state=j.optString("status");JSONObject item=data.item(id);boolean complete=state.equals("complete"),running=state.equals("downloading");
   String status=complete?Loc.t("Ready to watch offline"):j.optBoolean("readyPickup")||!j.has("status")&&DownloadHubActivity.pickupId(p,id)?DownloadHubActivity.pickupState(a,data,NoirApp.downloads,p):PhoneReadyJob.say(p.paused()?"Keep ready paused":!PhoneReadyJob.conditions(a).isEmpty()?PhoneReadyJob.conditions(a):!p.reason().isEmpty()?p.reason():!p.lastReason(id).isEmpty()?p.lastReason(id):"Preparing overnight");
   String[] parts=item!=null?new String[]{item.optString("title"),item.optBoolean("movie")?"":MainActivity.episode(item)}:j.has("season")?new String[]{j.optString("title"),MainActivity.episode(j)}:DownloadHubActivity.split(j.optString("title"));
   LinearLayout card=a.column();LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(a.dp(PhoneDensity.continueWidth()*.82f),-2);cp.setMargins(0,0,a.dp(PhoneDensity.cardGap()),0);card.setLayoutParams(cp);card.setTag("ready-card:"+id);
   FrameLayout art=a.ui.art(item!=null?item:j,false,-1,a.dp(PhoneDensity.continueArt()*.82f));View shade=new View(a);shade.setBackground(a.ui.fade(android.graphics.Color.TRANSPARENT,android.graphics.Color.argb(complete?120:190,0,0,0)));art.addView(shade,new FrameLayout.LayoutParams(-1,-1));
   TextView pill=a.ui.pill(complete?"Ready offline":running?"Downloading":"Waiting",complete?MainActivity.BLACK:MainActivity.WHITE,complete?MainActivity.GOLD:android.graphics.Color.argb(210,12,12,14));FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.START);pp.setMargins(a.dp(8),a.dp(8),a.dp(8),0);art.addView(pill,pp);
   if(complete){ImageView play=NoirIcons.icon(a,"play",22,MainActivity.GOLD);FrameLayout mark=new FrameLayout(a);mark.setBackground(MainActivity.bg(android.graphics.Color.argb(200,12,12,14),a.dp(22)));mark.addView(play,new FrameLayout.LayoutParams(a.dp(22),a.dp(22),Gravity.CENTER));art.addView(mark,new FrameLayout.LayoutParams(a.dp(44),a.dp(44),Gravity.CENTER));}
   Runnable open=complete?()->a.startActivity(new android.content.Intent(a,PlayerActivity.class).putExtra("id",id)):hub;art.setOnClickListener(v->open.run());art.setContentDescription(parts[0]+(parts[1].isEmpty()?"":" "+parts[1])+", "+status);card.addView(art);
   TextView title=a.text(parts[0],PhoneDensity.cardTitle(),MainActivity.WHITE);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setSingleLine();title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setPadding(0,a.dp(8),0,0);card.addView(title);
   TextView sub=a.text((parts[1].isEmpty()?"":NoirUi.ltr(parts[1])+" · ")+status,11.5f,complete?MainActivity.GOLD:MainActivity.MUTED);sub.setMaxLines(2);sub.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(sub);Motion.card(card);cards.add(card);}
  a.ui.rail(a.body,"Keep ready",Loc.t("Next episodes, downloaded ahead for you."),cards,hub);}
 String viewKey(){return "libraryView:"+(a.premium.collection.equals("My List")?"My List":libraryType);}
 String mode(){String v=a.data.prefs().optString(viewKey(),"Poster");return Arrays.asList("Poster","Landscape","List").contains(v)?v:"Poster";}
