 // Library: one kind row (All, Shows, Movies, My List), then one scrollable row of smart lists and collections; tapping the active one clears it.
 void libraryControls(){boolean mine=a.premium.collection.equals("My List");LinearLayout kinds=new LinearLayout(a);kinds.addView(a.ui.chip("All",()->{libraryType="All";if(mine)a.premium.collection="All";a.render();},libraryType.equals("All")&&!mine));for(String type:new String[]{"Shows","Movies"})kinds.addView(a.ui.chip(type,()->{libraryType=libraryType.equals(type)?"All":type;a.render();},type.equals(libraryType)));kinds.addView(a.ui.chip("My List",()->{a.premium.collection=mine?"All":"My List";a.render();},mine));a.body.addView(a.ui.row(kinds));
  LinearLayout smart=new LinearLayout(a);for(String id:SmartLists.IDS)smart.addView(a.ui.chip(SmartLists.name(id),()->{smartFilter=smartFilter.equals(id)?"All":id;a.render();},smartFilter.equals(id)));List<String> custom=a.premium.customCollections();for(String name:custom)smart.addView(a.ui.chip(name,()->{a.premium.collection=a.premium.collection.equals(name)?"All":name;a.render();},a.premium.collection.equals(name)));if(!custom.isEmpty())smart.addView(a.ui.chip(Loc.t("Manage"),()->a.premium.manageCollections(),false));a.body.addView(a.ui.row(smart));
  if(mine)a.body.addView(a.ui.chip("Still planned",()->{plannedOnly=!plannedOnly;a.render();},plannedOnly));}
 // Search first, with one View button beside it (card style and size).
 View searchRow(EditText q){LinearLayout r=new LinearLayout(a);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(q,new LinearLayout.LayoutParams(0,-2,1));r.addView(a.ui.chip(Loc.t("View"),()->viewSheet(),false));return r;}
 void viewSheet(){String key=viewKey();NoirSheet s=new NoirSheet(a,"View",null);for(String value:new String[]{"Poster","Landscape","List"})s.choice(value,null,value.equals(mode()),()->{a.data.pref(key,value);a.renderKeep();});TextView h=s.text("Card size",12,0xff9f9a93);h.setPadding(s.dp(4),s.dp(14),0,s.dp(2));s.body.addView(h);for(String value:new String[]{"Small","Medium","Large"})s.choice(value,null,value.equals(size()),()->{a.data.pref(key+":size",value);a.renderKeep();});s.show();}
 void choose(String title,String[] values,String key){String current=a.data.prefs().optString(key,values[key.endsWith(":size")?1:0]);NoirSheet s=new NoirSheet(a,title,null);for(String value:values)s.choice(value,null,value.equals(current),()->{a.data.pref(key,value);a.renderKeep();});s.show();}
 static Rect bounds(View v){Rect b=new Rect();v.getGlobalVisibleRect(b);return b;}
 static void enter(View body,Rect source){if(source==null||source.isEmpty()||!Motion.enabled(body))return;body.post(()->{if(!body.isAttachedToWindow())return;int[] at=new int[2];body.getLocationOnScreen(at);body.setPivotX(Math.max(0,Math.min(body.getWidth(),source.exactCenterX()-at[0])));body.setPivotY(Math.max(0,source.exactCenterY()-at[1]));body.setAlpha(0);body.setScaleX(.88f);body.setScaleY(.88f);body.animate().scaleX(1).scaleY(1).alpha(1).setStartDelay(0).setDuration(240).start();});}
 static void tint(View image,String key){View v=image;while(v.getParent() instanceof View){v=(View)v.getParent();if("art-tint".equals(v.getTag())){int color=Motion.placeholder(key);GradientDrawable tint=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{color,MainActivity.BLACK});v.setBackground(tint);break;}}}
